2	import { invoiceTotals } from './invoices.js';
3	import { balanceDue } from './payments.js';
4	
5	/**
6	 * Convert cents to euros string with 2 decimals.
7	 * @param {number} cents
8	 * @returns {string}
9	 */
10	function centsToEuros(cents) {
11	  return (cents / 100).toFixed(2);
12	}
13	
14	/**
15	 * Escape a field for CSV: double quotes around field if it contains comma, quote, or newline.
16	 * Double any quotes inside the field.
17	 * @param {*} field
18	 * @returns {string}
19	 */
20	function escapeCsvField(field) {
21	  const str = String(field);
22	  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
23	    return '"' + str.replace(/"/g, '""') + '"';
24	  }
25	  return str;
26	}
27	
28	/**
29	 * Export invoices as CSV.
30	 * @param {Array<any>} invoices
31	 * @returns {string}
32	 */
33	export function exportCsv(invoices) {
34	  const header = 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n';
35	
36	  const rows = invoices.map((invoice) => {
37	    const customerResult = getCustomer(invoice.customerId);
38	    const customerName = customerResult.ok ? customerResult.value.name : '';
39	    const totals = invoiceTotals(invoice);
40	    const due = balanceDue(invoice);
41	
42	    const fields = [
